tool_input_args.value:
node -e "
const subtotal = 460;
const pts = 500;
const rate = 100;
const maxPct = 0.50;
const maxDiscount = subtotal * maxPct;   // 230
const ptsValue = pts / rate;             // 5
const discount = Math.min(ptsValue, maxDiscount); // 5
const used = discount * rate;            // 500
const remaining = pts - used;            // 0
const total = subtotal - discount;       // 455
console.log('Subtotal:           \$' + subtotal.toFixed(2));
console.log('Max discount (50%): \$' + maxDiscount.toFixed(2));
console.log('Points used:        ' + used + '  (= \$' + discount.toFixed(2) + ')');
console.log('Points remaining:   ' + remaining);
console.log('Discount applied:   \$' + discount.toFixed(2));
console.log('New total:          \$' + total.toFixed(2));
"
